// -----------------------------------------------------
// ④ カタカナ → ひらがな
// -----------------------------------------------------

function katakanaToHiragana(value) {

  return String(value || "").replace(
    /[ァ-ヶ]/g,
    function(character) {

      return String.fromCharCode(
        character.charCodeAt(0) - 0x60
      );

    }
  );

}


// -----------------------------------------------------
// ⑤ 500人全員に検索ワードを自動追加
// -----------------------------------------------------

characters.forEach(function(character) {

  const workAliases =
    workSearchAliases[character.work] || [];

  const originalName =
    String(character.originalName || "");

  const originalParts = originalName
    .replace(/[\/(),.]/g, " ")
    .split(/\s+/)
    .filter(Boolean);

  let reversedName = "";

  if (originalParts.length >= 2) {

    reversedName =
      [...originalParts]
        .reverse()
        .join(" ");

  }

  const automaticKeywords = [

    character.id,

    String(character.id || "")
      .replace(/-/g, " "),

    String(character.id || "")
      .replace(/-/g, ""),

    character.name,

    katakanaToHiragana(
      character.name
    ),

    character.originalName,

    originalName.replace(
      /\s+/g,
      ""
    ),

    reversedName,

    character.work,

    katakanaToHiragana(
      character.work
    ),

    ...workAliases

  ].filter(Boolean);


  character.keywords = [

    ...new Set([

      ...(character.keywords || []),

      ...automaticKeywords

    ])

  ];

});


